"""Embed the shared contract schema in Kotlin; --check detects drift."""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    schema = json.loads((ROOT / "schema/play-surface.schema.json").read_text())
    literal = json.dumps(json.dumps(schema, separators=(",", ":"))).replace("$", "\\$")
    text = (
        "// Generated by tools/generate_play_surface.py; do not edit.\n"
        "package dev.cyclone.cloak.forge\n\n"
        "internal object PlaySurfaceRules {\n    const val json = " + literal + "\n}\n"
    )
    target = (
        ROOT / "android/app/src/main/java/dev/cyclone/cloak/forge/PlaySurfaceRules.kt"
    )
    if "--check" in sys.argv:
        assert target.read_text() == text, "Regenerate PlaySurfaceRules.kt"
    else:
        target.write_text(text, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
